const periodReportSummary = `-- name: PeriodReportSummary :one

WITH inv AS (
  SELECT bi.id, bi.branch_id, bi.client_ref, bi.kind, bi.branch_invoice_code, bi.branch_cashbox_account_id, bi.branch_shift_id, bi.branch_inventory_id, bi.branch_client_id, bi.related_client_ref, bi.discount, bi.subtotal, bi.discounted_total, bi.grand_total, bi.loyalty_points_delta, bi.occurred_at, bi.received_at, bi.salesperson_name, bi.historical, bi.client_uid, bi.register_id, bi.cancelled_at, bi.salesperson_id, bi.lbp_total, bi.lbp_rate, bi.invoice_discount, bi.invoice_discount_name, COALESCE(cu.id, cl.client_id) AS client_id
  FROM branch_invoices bi
  JOIN branches b ON b.id = bi.branch_id
  LEFT JOIN clients cu ON cu.uid = bi.client_uid
  LEFT JOIN client_links cl ON cl.register_id = bi.register_id AND cl.branch_client_id = bi.branch_client_id
  -- A day either side for the index; the exact local days are checked next.
  WHERE bi.occurred_at >= $2::date - 1 AND bi.occurred_at < $3::date + 2
    AND (bi.occurred_at AT TIME ZONE b.timezone)::date BETWEEN $2::date AND $3::date
    AND (COALESCE(cardinality($4::bigint[]), 0) = 0 OR bi.branch_id = ANY($4::bigint[]))
    AND NOT b.hidden_from_reports
    AND bi.register_id NOT IN (SELECT r.id FROM branch_registers r WHERE r.hidden_from_reports)
    AND bi.cancelled_at IS NULL
    AND NOT EXISTS (
        -- customers left out of reports (report settings)
        SELECT 1 FROM clients xc
        WHERE xc.id = ANY($5::bigint[])
          AND (xc.uid = bi.client_uid OR EXISTS (
            SELECT 1 FROM client_links xl
            WHERE xl.client_id = xc.id AND xl.register_id = bi.register_id AND xl.branch_client_id = bi.branch_client_id)))
)
SELECT
  count(*) FILTER (WHERE kind = 'sales')::bigint AS sales_count,
  COALESCE(sum(grand_total) FILTER (WHERE kind = 'sales'), 0)::bigint AS sales_total,
  count(*) FILTER (WHERE kind <> 'sales')::bigint AS returns_count,
  COALESCE(sum(grand_total) FILTER (WHERE kind <> 'sales'), 0)::bigint AS returns_total,
  COALESCE(sum(grand_total), 0)::bigint AS net_total,
  COALESCE(sum(subtotal - discounted_total) FILTER (WHERE kind = 'sales'), 0)::bigint AS discount_total,
  count(*) FILTER (WHERE kind = 'sales' AND subtotal > discounted_total)::bigint AS discounted_count,
  COALESCE(max(grand_total) FILTER (WHERE kind = 'sales'), 0)::bigint AS biggest_sale,
  count(*) FILTER (WHERE kind = 'sales' AND client_id IS NOT NULL)::bigint AS named_sales_count,
  count(DISTINCT client_id)::bigint AS clients_served,
  count(DISTINCT (occurred_at AT TIME ZONE 'Asia/Beirut')::date) FILTER (WHERE kind = 'sales')::bigint AS selling_days,
  COALESCE((
    SELECT sum(i.quantity) FROM branch_invoice_items i JOIN inv ON inv.id = i.branch_invoice_id WHERE inv.kind = 'sales' AND NOT EXISTS (SELECT 1 FROM product_variants xv WHERE xv.uid = i.product_uid AND xv.product_id = ANY($1::bigint[]))
  ), 0)::bigint AS items_sold,
  COALESCE((
    SELECT -sum(i.quantity) FROM branch_invoice_items i JOIN inv ON inv.id = i.branch_invoice_id WHERE i.quantity < 0 AND NOT EXISTS (SELECT 1 FROM product_variants xv WHERE xv.uid = i.product_uid AND xv.product_id = ANY($1::bigint[]))
  ), 0)::bigint AS items_returned
FROM inv
`

type PeriodReportSummaryParams struct {
	ExcludeProductIds []int64   `json:"exclude_product_ids"`
	FromDay           time.Time `json:"from_day"`
	ToDay             time.Time `json:"to_day"`
	BranchIds         []int64   `json:"branch_ids"`
	ExcludeClientIds  []int64   `json:"exclude_client_ids"`
}

type PeriodReportSummaryRow struct {
	SalesCount      int64 `json:"sales_count"`
	SalesTotal      int64 `json:"sales_total"`
	ReturnsCount    int64 `json:"returns_count"`
	ReturnsTotal    int64 `json:"returns_total"`
	NetTotal        int64 `json:"net_total"`
	DiscountTotal   int64 `json:"discount_total"`
	DiscountedCount int64 `json:"discounted_count"`
	BiggestSale     int64 `json:"biggest_sale"`
	NamedSalesCount int64 `json:"named_sales_count"`
	ClientsServed   int64 `json:"clients_served"`
	SellingDays     int64 `json:"selling_days"`
	ItemsSold       int64 `json:"items_sold"`
	ItemsReturned   int64 `json:"items_returned"`
}

// The Reports page (api/reports.go): end-of-period reports over the tills'
// invoices -- sales, salespersons, customers, products, busy times and
// payments. Every query takes the same scope as the Busy Hours page:
// [from_day, to_day] are calendar days in each branch's own time zone, an
// empty branch_ids means every branch, and cancelled sales and branches or
// registers hidden from reports are left out. Amounts are cents; returns and
// exchanges carry their own sign (negative for money given back), so a plain
// SUM nets them.
func (q *Queries) PeriodReportSummary(ctx context.Context, arg PeriodReportSummaryParams) (PeriodReportSummaryRow, error) {
	row := q.db.QueryRowContext(ctx, periodReportSummary,
		pq.Array(arg.ExcludeProductIds),
		arg.FromDay,
		arg.ToDay,
		pq.Array(arg.BranchIds),
		pq.Array(arg.ExcludeClientIds),
	)
	var i PeriodReportSummaryRow
	err := row.Scan(
		&i.SalesCount,
		&i.SalesTotal,
		&i.ReturnsCount,
		&i.ReturnsTotal,
		&i.NetTotal,
		&i.DiscountTotal,
		&i.DiscountedCount,
		&i.BiggestSale,
		&i.NamedSalesCount,
		&i.ClientsServed,
		&i.SellingDays,
		&i.ItemsSold,
		&i.ItemsReturned,
	)
	return i, err
}

